DELIMITER $$
CREATE TRIGGER `validar_serie_antes_insertar` BEFORE INSERT ON `instrumentos` FOR EACH ROW BEGIN
    IF NEW.serie NOT LIKE 'MD-%' AND NEW.serie NOT LIKE 'DT-%' AND NEW.serie NOT LIKE 'CP-%' AND NEW.serie NOT LIKE 'EN-%' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Error: La serie debe empezar con MD-, DT-, CP- o EN-';
    END IF;
END
$$
DELIMITER ;

